//! WPT `encoding/`: the label, single-byte and UTF-16 cases of Phase 4
//! items 4.2 and 4.3, as Rust tables.
//!
//! WPT keeps these as JavaScript. Each rule below names the file and the
//! literal it reads; the literal must appear exactly where the rule says,
//! so an upstream change that moves or reshapes it fails the conversion
//! rather than dropping cases. Where a test computes its expectations with
//! code (the whitespace variants of the label test, the single-byte
//! expectations), the converter checks that the code is the text it
//! expects and the generated table carries the data that code reads; the
//! conformance test applies the same rule, which the generated file's
//! comments state.
//!
//! `encodings.js` is `resources/encodings.js` and `single-byte-decoder.js`
//! is `resources/single-byte-decoder.js` (suite directories are flat).

use std::fmt::Write as _;
use std::path::Path;

use super::js::{Node, Parser, find_all, scalars};

/// The files vendored for this suite (besides LICENSE.md and SOURCE.md).
pub const FILES: &[&str] = &[
    "encodings.js",
    "single-byte-decoder.any.js",
    "single-byte-decoder.js",
    "textdecoder-fatal-single-byte.any.js",
    "textdecoder-labels.any.js",
    "textdecoder-utf16-surrogates.any.js",
];

struct Source {
    file: &'static str,
    text: String,
}

impl Source {
    /// The literal right after the only occurrence of `marker`.
    fn after_only(&self, marker: &str) -> Result<Node, String> {
        match find_all(&self.text, marker).as_slice() {
            [pos] => Parser::at(&self.text, *pos).literal(),
            found => Err(format!(
                "expected {marker:?} exactly once, found {} times",
                found.len()
            )),
        }
        .map_err(|e| format!("{}: {e}", self.file))
    }

    /// Fail unless `text` occurs in the file (code the tables rely on).
    fn require(&self, text: &str) -> Result<(), String> {
        if self.text.contains(text) {
            Ok(())
        } else {
            Err(format!(
                "{}: expected the code {text:?}; the test changed shape",
                self.file
            ))
        }
    }
}

/// Convert the suite in `dir` to the body of a Rust source file.
pub fn convert(dir: &Path) -> Result<String, String> {
    let mut sources = Vec::new();
    for file in FILES {
        let path = dir.join(file);
        let text =
            std::fs::read_to_string(&path).map_err(|e| format!("{}: {e}", path.display()))?;
        sources.push(Source { file, text });
    }
    let get = |file: &str| {
        sources
            .iter()
            .find(|s| s.file == file)
            .ok_or_else(|| format!("{file}: not loaded"))
    };
    let mut out = String::from(
        "// @generated by `cargo xtask testdata` from tests/data/wpt-encoding-legacy/.\n\
         // Do not edit: `cargo xtask verify` fails if this differs from what the\n\
         // converter (xtask/src/testdata/wpt_encoding_legacy.rs) produces.\n\
         // Source, commit and license: tests/data/wpt-encoding-legacy/SOURCE.md.\n\n",
    );

    // encodings.js: `const encodings_table = [{encodings: [{labels, name}],
    // heading}, ...]`, "Straight from" the standard's encodings.json.
    let table = get("encodings.js")?.after_only("const encodings_table =\n")?;
    let mut labels = Vec::new();
    let mut single_byte = Vec::new();
    for group in table.array()? {
        let heading = group.field("heading")?.string()?;
        for e in group.field("encodings")?.array()? {
            let name = e.field("name")?.string()?;
            if heading == "Legacy single-byte encodings" {
                single_byte.push((name.clone(), e.field("labels")?.array()?.to_vec()));
            }
            for l in e.field("labels")?.array()? {
                labels.push((l.line, l.string()?, name.clone()));
            }
        }
    }

    // textdecoder-labels.any.js: every label of every encoding but
    // replacement, as given, upper-cased, and with each whitespace
    // character before, after and around it, must give the encoding.
    let s = get("textdecoder-labels.any.js")?;
    let ws = s.after_only("var whitespace = ")?;
    s.require("return encoding.name !== 'replacement';")?;
    s.require("new TextDecoder(label.toUpperCase()).encoding, textDecoderName")?;
    s.require("new TextDecoder(ws + label).encoding, textDecoderName")?;
    s.require("new TextDecoder(label + ws).encoding, textDecoderName")?;
    s.require("new TextDecoder(ws + label + ws).encoding, textDecoderName")?;
    out.push_str(
        "/// textdecoder-labels.any.js: each label, upper-cased, and with each of\n\
         /// WHITESPACE before, after and around it, names the encoding. The test\n\
         /// skips replacement's labels (`new TextDecoder` rejects that encoding,\n\
         /// Encoding §7.2); they are listed with `in_wpt: false` and checked the\n\
         /// same way, but not counted as WPT cases.\n\
         const LABELS: &[Label] = &[\n",
    );
    for (line, label, name) in &labels {
        writeln!(
            out,
            "    Label {{ line: {line}, label: {label:?}, name: {name:?}, in_wpt: {} }},",
            name != "replacement"
        )
        .map_err(|e| e.to_string())?;
    }
    out.push_str("];\n\n/// textdecoder-labels.any.js: `var whitespace`.\nconst WHITESPACE: &[u8] = &[");
    let ws: Vec<String> = ws
        .array()?
        .iter()
        .map(|n| {
            let units = n.str_units()?;
            match units {
                [u] => u8::try_from(*u)
                    .map(|b| format!("0x{b:02X}"))
                    .map_err(|e| e.to_string()),
                _ => Err(format!("line {}: not one character", n.line)),
            }
        })
        .collect::<Result<_, _>>()?;
    out.push_str(&ws.join(", "));
    out.push_str("];\n\n");

    // single-byte-decoder.js: `singleByteIndexes = {"IBM866": [...], ...}`,
    // WPT's own copy of the indexes; single-byte-decoder.any.js decodes
    // bytes 0 to 254 with each label of each single-byte encoding.
    let r = get("single-byte-decoder.js")?;
    r.require("return group.heading === \"Legacy single-byte encodings\";")?;
    let indexes = r.after_only("singleByteIndexes = ")?;
    let t = get("single-byte-decoder.any.js")?;
    t.require("var buffer = new ArrayBuffer(255),")?;
    t.require("view[i] = i")?;
    t.require("if(encoding == \"ISO-8859-8-I\") {\n    encoding = \"ISO-8859-8\"\n  }")?;
    t.require("expectedCp = (i < 0x80) ? i : singleByteIndexes[encoding][i-0x80]")?;
    t.require("if(expectedCp == null) {\n      expectedCp = 0xFFFD\n    }")?;
    t.require("assert_equals(d.encoding, encoding.name.toLowerCase())")?;
    out.push_str(
        "/// single-byte-decoder.js: `singleByteIndexes`, WPT's copy of each index\n\
         /// (`None` for null).\n\
         const SINGLE_BYTE_INDEXES: &[Index] = &[\n",
    );
    let Some(index_fields) = (match &indexes.lit {
        super::js::Lit::Obj(fields) => Some(fields),
        _ => None,
    }) else {
        return Err(format!("{}: singleByteIndexes is not an object", r.file));
    };
    for (name, entries) in index_fields {
        let entries = entries.array()?;
        if entries.len() != 128 {
            return Err(format!("{}: index {name} has {} entries", r.file, entries.len()));
        }
        let rows: Vec<String> = entries
            .iter()
            .map(|n| {
                if n.is_null() {
                    Ok("None".to_owned())
                } else {
                    n.num().map(|v| format!("Some(0x{v:04X})"))
                }
            })
            .collect::<Result<_, String>>()?;
        writeln!(
            out,
            "    Index {{ name: {name:?}, table: &[{}] }},",
            rows.join(", ")
        )
        .map_err(|e| e.to_string())?;
    }
    out.push_str(
        "];\n\n\
         /// single-byte-decoder.any.js (\"TextDecoder\" variant): decoding bytes 0\n\
         /// to 254 with `label` gives encoding `name`, and byte i decodes to i\n\
         /// below 0x80, else to entry i - 0x80 of SINGLE_BYTE_INDEXES[index], or\n\
         /// U+FFFD where that is null. `index` is the name, except that\n\
         /// ISO-8859-8-I reads ISO-8859-8 (the test's own rule).\n\
         const SINGLE_BYTE: &[SingleByte] = &[\n",
    );
    for (name, labels) in &single_byte {
        let index = if name == "ISO-8859-8-I" {
            "ISO-8859-8"
        } else {
            name.as_str()
        };
        if !index_fields.iter().any(|(k, _)| k == index) {
            return Err(format!("{}: no index for {name}", r.file));
        }
        for l in labels {
            writeln!(
                out,
                "    SingleByte {{ name: {name:?}, label: {:?}, index: {index:?} }},",
                l.string()?
            )
            .map_err(|e| e.to_string())?;
        }
    }
    out.push_str("];\n\n");

    // textdecoder-fatal-single-byte.any.js: `var singleByteEncodings =
    // [{encoding, bad}]`; with `fatal: true`, decoding the one byte i fails
    // exactly when i is in `bad`, for i in 0 to 255.
    let s = get("textdecoder-fatal-single-byte.any.js")?;
    s.require("for (var i = 0; i < 256; ++i) {")?;
    s.require("if (t.bad.indexOf(i) != -1) {")?;
    s.require("new TextDecoder(t.encoding, {fatal: true}).decode(new Uint8Array([i]));")?;
    out.push_str(
        "/// textdecoder-fatal-single-byte.any.js: with `fatal: true`, decoding the\n\
         /// single byte i (0 to 255) fails exactly when i is in `bad`.\n\
         const FATAL_SINGLE_BYTE: &[Fatal] = &[\n",
    );
    for row in s.after_only("var singleByteEncodings = ")?.array()? {
        let bad: Vec<String> = row
            .field("bad")?
            .bytes()?
            .iter()
            .map(|b| format!("0x{b:02X}"))
            .collect();
        writeln!(
            out,
            "    Fatal {{ line: {}, encoding: {:?}, bad: &[{}] }},",
            row.line,
            row.field("encoding")?.string()?,
            bad.join(", ")
        )
        .map_err(|e| e.to_string())?;
    }
    out.push_str("];\n\n");

    // textdecoder-utf16-surrogates.any.js: `var bad = [{encoding, input,
    // expected, name}]`; replacement decoding gives `expected`, fatal fails.
    let s = get("textdecoder-utf16-surrogates.any.js")?;
    s.require("assert_equals(new TextDecoder(t.encoding).decode(new Uint8Array(t.input)), t.expected);")?;
    s.require("new TextDecoder(t.encoding, {fatal: true}).decode(new Uint8Array(t.input))")?;
    out.push_str(
        "/// textdecoder-utf16-surrogates.any.js: decoding `input` gives `expected`,\n\
         /// and with `fatal: true` fails.\n\
         const UTF16_SURROGATES: &[Utf16] = &[\n",
    );
    for row in s.after_only("var bad = ")?.array()? {
        let input: Vec<String> = row
            .field("input")?
            .bytes()?
            .iter()
            .map(|b| format!("0x{b:02X}"))
            .collect();
        let expected = scalars(row.field("expected")?.str_units()?)
            .map_err(|e| format!("{}:{}: {e}", s.file, row.line))?;
        let expected: Vec<String> = expected.iter().map(|c| format!("0x{c:04X}")).collect();
        writeln!(
            out,
            "    Utf16 {{ line: {}, encoding: {:?}, name: {:?}, input: &[{}], expected: &[{}] }},",
            row.line,
            row.field("encoding")?.string()?,
            row.field("name")?.string()?,
            input.join(", "),
            expected.join(", ")
        )
        .map_err(|e| e.to_string())?;
    }
    out.push_str("];\n");
    Ok(out)
}
